from html.parser import HTMLParser
from pathlib import Path
import re

BLOCK_TAGS = {
    'p','br','hr','div','tr','td','table','h1','h2','h3','h4','h5','h6',
    'li','ul','ol','pre','blockquote','center','font'
}

class TextExtractor(HTMLParser):
    def __init__(self):
        super().__init__()
        self.parts = []
        self._skip = False
    def handle_starttag(self, tag, attrs):
        if tag in ('script','style'):
            self._skip = True
            return
        if tag in BLOCK_TAGS:
            self.parts.append('\n')
    def handle_endtag(self, tag):
        if tag in ('script','style'):
            self._skip = False
            return
        if tag in BLOCK_TAGS:
            self.parts.append('\n')
    def handle_data(self, data):
        if self._skip:
            return
        self.parts.append(data)


def extract(path):
    html = Path(path).read_text(errors='ignore')
    p = TextExtractor()
    p.feed(html)
    text = ''.join(p.parts)
    # Normalize line breaks
    lines = [re.sub(r'\s+', ' ', l).strip() for l in text.splitlines()]
    lines = [l for l in lines if l]
    # Remove YC banner lines
    filtered = []
    for l in lines:
        if l in {'Want to start a startup? Get funded by', 'Y Combinator.'}:
            continue
        filtered.append(l)
    return filtered

for fn in ['/root/do_things_dont_scale.html','/root/founder_mode.html']:
    print('\n==', fn)
    lines = extract(fn)
    for l in lines[:20]:
        print(l)
