import json, os, time, socket
from pathlib import Path
from urllib import request, error

api_key = os.environ.get('OPENAI_API_KEY')
if not api_key:
    raise SystemExit('OPENAI_API_KEY not set')

text = Path('/root/essay_text.txt').read_text()

max_chars = 2000
lines = text.splitlines()
chunks = []
current = ''
for line in lines:
    if line.strip() == '':
        append = '\n'
    else:
        append = line.strip() + '\n'
    if len(current) + len(append) > max_chars and current.strip():
        chunks.append(current.strip())
        current = append
    else:
        current += append
if current.strip():
    chunks.append(current.strip())

out_dir = Path('/root/tts_parts')
if out_dir.exists():
    for p in out_dir.glob('part_*.mp3'):
        p.unlink()
else:
    out_dir.mkdir()

url = 'https://api.openai.com/v1/audio/speech'
headers = {
    'Authorization': f'Bearer {api_key}',
    'Content-Type': 'application/json'
}

print(f'Total chunks: {len(chunks)}')

socket.setdefaulttimeout(180)

for i, chunk in enumerate(chunks, 1):
    payload = {
        'model': 'gpt-4o-mini-tts',
        'voice': 'alloy',
        'input': chunk,
        'format': 'mp3'
    }
    data = json.dumps(payload).encode('utf-8')
    req = request.Request(url, data=data, headers=headers, method='POST')
    attempt = 0
    while True:
        attempt += 1
        try:
            print(f'Chunk {i}/{len(chunks)} attempt {attempt} (chars {len(chunk)})...')
            with request.urlopen(req, timeout=180) as resp:
                audio = resp.read()
            break
        except Exception as e:
            print(f'Chunk {i} failed on attempt {attempt}: {e}')
            if attempt >= 3:
                raise SystemExit(f'Chunk {i} failed after 3 attempts')
            time.sleep(5)
    part_path = out_dir / f'part_{i:03d}.mp3'
    part_path.write_bytes(audio)
    print('Wrote', part_path, 'bytes', len(audio))
    time.sleep(0.2)

print('Done')
